using UnityEngine;

namespace WattsTap.Core.Configs.Referral
{
    [CreateAssetMenu(fileName = "ReferralConfig", menuName = "WattsTap/Configs/Referral/ReferralConfig")]
    public class ReferralConfig : BaseConfig
    {
        [Header("API Settings")]
        [Tooltip("Base URL for the referral API")]
        public string BaseUrl = "http://localhost:8000";

        [Tooltip("Request timeout in seconds")]
        public int RequestTimeout = 30;

        [Header("Bot Settings")]
        [Tooltip("Telegram bot username for invite links")]
        public string BotUsername = "wattstap_eu_bot";

        [Header("Default Values")]
        [Tooltip("Default bonus per friend if not provided by server")]
        public int DefaultBonusPerFriend = 5000;

        [Header("Share Settings")]
        [Tooltip("Text to share when inviting friends")]
        public string ShareText = "Join me in WattsTap and get bonus coins! ⚡";

        /// <summary>
        /// Constructs the full invite link from a referral code
        /// </summary>
        public string GetInviteLink(string referralCode)
        {
            return $"https://t.me/{BotUsername}?start=REF_{referralCode}";
        }
    }
}

using UnityEngine;

namespace WattsTap.Core.Configs.Referral
{
    [CreateAssetMenu(fileName = "ReferralConfig", menuName = "WattsTap/Configs/Referral/ReferralConfig")]
    public class ReferralConfig : BaseConfig
    {
        [Header("API Settings")]
        [Tooltip("Base URL for the referral API")]
        public string BaseUrl = "http://localhost:8000";

        [Tooltip("Request timeout in seconds")]
        public int RequestTimeout = 30;

        [Header("Bot Settings")]
        [Tooltip("Telegram bot username for invite links")]
        public string BotUsername = "wattstap_eu_bot";

        [Tooltip("Mini App short name (set in BotFather)")]
        public string MiniAppShortName = "app";

        [Header("Default Values")]
        [Tooltip("Default bonus per friend if not provided by server")]
        public int DefaultBonusPerFriend = 5000;

        [Header("Share Settings")]
        [Tooltip("Text to share when inviting friends")]
        public string ShareText = "Join me in WattsTap and get bonus coins! ⚡";

        /// <summary>
        /// Constructs the full invite link from a referral code.
        /// Uses startapp parameter for Mini Apps (not start which is for bot commands).
        /// Format: https://t.me/BotUsername/AppShortName?startapp=REF_CODE
        /// </summary>
        public string GetInviteLink(string referralCode)
        {
            // Use startapp for Mini Apps, not start
            // start= sends parameter to bot via /start command
            // startapp= sends parameter to Mini App via initDataUnsafe.start_param
            return $"https://t.me/{BotUsername}/{MiniAppShortName}?startapp=REF_{referralCode}";
        }
    }
}

using System;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using UnityEngine;
using UnityEngine.Networking;
using WattsTap.Constants;
using WattsTap.Core.Configs;
using WattsTap.Core.Configs.Telegram;

namespace WattsTap.Core.React
{
    public class TelegramService : MonoBehaviour, ITelegramService
    {
        public enum TelegramAppEnvironment
        {
            Unknown = 0,
            MobileClient,
            DesktopClient,
            DesktopWeb,
            MobileWeb
        }

        [Serializable]
        public class SafeArea
        {
            public float Top;
            public float Bottom;
            public float Left;
            public float Right;
            public float ContentSafeAreaTop; // Additional top inset from contentSafeAreaInset
        }

        [Serializable]
        public class User
        {
            public long id;
            public string first_name;
            public string last_name;
            public string username;
            public string language_code;
            public bool is_premium;
            public bool added_to_attachment_menu;
            public bool allows_write_to_pm;
            public string photo_url;
            public string created_at;
            public string updated_at;
            public string token;

            public override string ToString()
            {
                return $"<color=#FFFF00>User ID: {id}, Name: {first_name} {last_name}, Username: {username}, Language: {language_code}, Is Premium: {is_premium}, " +
                       $"Added to Attachment Menu: {added_to_attachment_menu}, Allows Write to PM: {allows_write_to_pm}, Photo URL: {photo_url}, " +
                       $"Created At: {created_at}, Updated At: {updated_at}, Token: {token} </color>";
            }
        }

        [Serializable]
        private class Payload
        {
            public long chat_id;
            public string text;
        }

        [DllImport("__Internal")]
        private static extern void GetTelegramWebAppInitDataUnsafeUser();

        [SerializeField] private string _botToken;

#if UNITY_EDITOR
        [Header("Debug Settings (Editor Only)")]
        [SerializeField] private bool _useDebugSafeArea = false;
        [SerializeField] private SafeArea _debugSafeAreaInsets = new SafeArea();
#endif

        public string Id { get; private set; }
        public string UserName { get; private set; }
        public string InitData { get; private set; }
        public TelegramAppEnvironment AppEnvironment { get; private set; } = TelegramAppEnvironment.Unknown;

#if UNITY_EDITOR       
        public bool DebugSafeAreaInsets => _useDebugSafeArea;
#endif
        public SafeArea SafeAreaInsets => _safeAreaInsets;

        public int InitializationOrder => 1000;
        public bool IsInitialized { get; private set; }

        public event Action<string> OnReceivedUserId;
        public event Action<string> OnReceivedUserName;
        public event Action<string> OnReceivedInitData;
        public event Action<SafeArea> OnReceivedSafeAreaInsets;
        public event Action<TelegramAppEnvironment> OnReceivedAppEnvironment;
        public event Action<string> OnReceivedStartParam;

        private SafeArea _safeAreaInsets = null;

        /// <summary>
        /// Start parameter from deep link (referral code)
        /// Example: t.me/WattsTapBot?start=REF_ABC123
        /// </summary>
        public string StartParam { get; private set; }

        /// <summary>
        /// Returns true if there's a referral code in start_param
        /// </summary>
        public bool HasReferralCode => !string.IsNullOrEmpty(StartParam);

        public static long GetUserIdFromInitData(string initData)
        {
            var match = Regex.Match(initData, @"user=([^&]+)");

            if (!match.Success)
                return -1;

            var userJsonEncoded = match.Groups[1].Value;
            var userJson = Uri.UnescapeDataString(userJsonEncoded);

            var user = JsonUtility.FromJson<User>(userJson);
            return user?.id ?? -1;
        }

        /// <summary>
        /// Parses Telegram initData and extracts the User object
        /// Example: query_id=AAE71KpqAwAAADvUqmrbRN4l&user=%7B%22id%22%3A8232031291%2C%22first_name%22%3A%22Islamov%22...
        /// </summary>
        /// <param name="initData">The raw initData string from Telegram Web App</param>
        /// <returns>Parsed User object or null if parsing fails</returns>
        public static User ParseUserFromInitData(string initData)
        {
            if (string.IsNullOrEmpty(initData))
            {
                Debug.LogWarning("InitData is null or empty");
                return null;
            }

            var match = Regex.Match(initData, @"user=([^&]+)");

            if (!match.Success)
            {
                Debug.LogWarning("Failed to find user parameter in initData");
                return null;
            }

            var userJsonEncoded = match.Groups[1].Value;
            var userJson = Uri.UnescapeDataString(userJsonEncoded);

            try
            {
                var user = JsonUtility.FromJson<User>(userJson);
                if (user == null)
                {
                    Debug.LogWarning("Failed to deserialize user JSON");
                    return null;
                }

                Debug.Log($"Successfully parsed user from initData: {user}");
                return user;
            }
            catch (Exception ex)
            {
                Debug.LogError($"Error parsing user from initData: {ex.Message}");
                return null;
            }
        }

        public void Initialize()
        {
            if (IsInitialized)
            {
                return;
            }

            IsInitialized = true;

#if !UNITY_WEBGL || UNITY_EDITOR
             var configService = ServiceLocator.Get<IConfigService>();
             TelegramDebugData telegramDebugData = configService.GetConfig<TelegramDebugData>(ConfigsConstants.TelegramDebugData);
             ReceiveInitData(telegramDebugData.InitData);
#endif

#if UNITY_EDITOR
            if (_useDebugSafeArea)
            {
                _safeAreaInsets = _debugSafeAreaInsets;
                Debug.Log($"Using debug safe area insets: Top={_safeAreaInsets.Top}, Bottom={_safeAreaInsets.Bottom}, Left={_safeAreaInsets.Left}, Right={_safeAreaInsets.Right}");

                // Trigger the event so TelegramSafeZoneApplier can apply the debug safe area
                OnReceivedSafeAreaInsets?.Invoke(_safeAreaInsets);
            }
#endif
        }

        public void Shutdown()
        {
            if (!IsInitialized)
            {
                return;
            }

            IsInitialized = false;
        }

        public void ReceiveUserId(string id)
        {
            Id = id;
            OnReceivedUserId?.Invoke(id);
            Debug.Log($"Received User ID: {id}");
        }

        public void ReceiveUserName(string userName)
        {
            UserName = userName;
            OnReceivedUserName?.Invoke(userName);
            Debug.Log($"Received User Name: {userName}");
        }

        public void ReceiveInitData(string initData)
        {
            InitData = initData;
            OnReceivedInitData?.Invoke(initData);
            Debug.Log($"Received Init Data: {initData}");
        }

        public void ReceiveSafeAreaInsets(string safeAreaInsets)
        {
            var result = safeAreaInsets.Split(',');
            _safeAreaInsets = new SafeArea
            {
                Top = float.Parse(result[0]),
                Left = float.Parse(result[1]),
                Bottom = float.Parse(result[2]),
                Right = float.Parse(result[3]),
                ContentSafeAreaTop = float.Parse(result[4]) // Parse the additional top inset
            };

            OnReceivedSafeAreaInsets?.Invoke(_safeAreaInsets);
        }

        public void ReceiveAppEnvironment(string environment)
        {
            if (string.IsNullOrEmpty(environment) ||
                !Enum.TryParse(environment, true, out TelegramAppEnvironment parsedEnvironment))
            {
                parsedEnvironment = TelegramAppEnvironment.Unknown;
            }

            AppEnvironment = parsedEnvironment;
            OnReceivedAppEnvironment?.Invoke(parsedEnvironment);
            Debug.LogError($"Received Telegram environment: {parsedEnvironment}");
        }

        /// <summary>
        /// Receives start_param from JavaScript (referral code from deep link)
        /// Called from WebGL JavaScript
        /// </summary>
        public void ReceiveStartParam(string startParam)
        {
            StartParam = startParam;
            OnReceivedStartParam?.Invoke(startParam);

            if (!string.IsNullOrEmpty(startParam))
            {
                Debug.Log($"<color=#00FF00>[TelegramService] Received Start Param (Referral): {startParam}</color>");
            }
        }

        /// <summary>
        /// Gets the clean referral code without the REF_ prefix
        /// </summary>
        /// <returns>Clean referral code or null</returns>
        public string GetCleanReferralCode()
        {
            if (string.IsNullOrEmpty(StartParam))
                return null;

            // Remove REF_ prefix if present
            if (StartParam.StartsWith("REF_", StringComparison.OrdinalIgnoreCase))
            {
                return StartParam.Substring(4).ToUpperInvariant();
            }

            return StartParam.ToUpperInvariant();
        }

        /// <summary>
        /// Parses start_param from initData string (fallback method)
        /// </summary>
        public static string ParseStartParamFromInitData(string initData)
        {
            if (string.IsNullOrEmpty(initData))
                return null;

            var match = Regex.Match(initData, @"start_param=([^&]+)");
            if (match.Success)
            {
                return Uri.UnescapeDataString(match.Groups[1].Value);
            }

            return null;
        }

        public void OnCreateUnityInstance()
        {
            GetTelegramWebAppInitDataUnsafeUser();
        }

//         public async UniTask SendMessageAsync(string message, long chatId, CancellationToken cancellationToken = default)
